using System.Runtime.InteropServices;
using Microsoft.Win32.SafeHandles;

// Stand-ins for BCL APIs that exist in the .NET version the Process sources in dotnet/runtime main target,
// but not in the .NET 10 runtime used to run this benchmark. They are only used on process start code paths
// that the benchmark does not exercise.
internal static class ShimApi
{
    public const PosixSignal SIGKILL = (PosixSignal)(-9);

    public static SafeFileHandle OpenNullHandle() => File.OpenHandle("/dev/null", FileMode.Open, FileAccess.ReadWrite);

    public static SafeFileHandle OpenStdin() => new SafeFileHandle((IntPtr)0, ownsHandle: false);

    public static SafeFileHandle OpenStdout() => new SafeFileHandle((IntPtr)1, ownsHandle: false);

    public static SafeFileHandle OpenStderr() => new SafeFileHandle((IntPtr)2, ownsHandle: false);

    public static void CreateAnonymousPipe(out SafeFileHandle read, out SafeFileHandle write, bool asyncRead = false)
        => throw new PlatformNotSupportedException();
}
