`Program.cs`

```csharp
using System.Diagnostics;
using System.IO.Pipes;
using System.Net.Sockets;
using System.Text;

internal static class Program
{
    private static readonly List<object> s_keepAlive = new();
    private static readonly ManualResetEventSlim s_stop = new(false);

    private static int Main(string[] args)
    {
        // args: <variant> <threads> <fds> [json-output-file]
        string variant = args[0];
        int targetThreads = int.Parse(args[1]);
        int targetFds = int.Parse(args[2]);
        string? output = args.Length > 3 ? args[3] : null;

        EnsureThreads(targetThreads);
        EnsureFds(targetFds);

        int actualThreads = ReadStatusInt("Threads:");
        int actualFds = Directory.GetFileSystemEntries("/proc/self/fd").Length;

        using Process p = Process.GetCurrentProcess();

        var results = new List<(string Name, double Ns, double Bytes, double MinNs, double MaxNs)>();

        void Bench(string name, Action action, int samples = 7, int sampleMs = 250)
        {
            var r = Measure(action, samples, sampleMs);
            results.Add((name, r.Ns, r.Bytes, r.MinNs, r.MaxNs));
            Console.Error.WriteLine($"[{variant} t={actualThreads} fd={actualFds}] {name,-34} {r.Ns / 1000.0,10:F1} us  {r.Bytes,10:F0} B");
        }

        p.Refresh();
        int handleCount = p.HandleCount;
        int filesOnly = Directory.GetFiles("/proc/self/fd").Length;
        int allEntries = Directory.GetFileSystemEntries("/proc/self/fd").Length;
        Console.Error.WriteLine($"[{variant}] Process type from '{typeof(Process).Assembly.GetName().Name}'; HandleCount={handleCount}; Directory.GetFiles={filesOnly}; Directory.GetFileSystemEntries={allEntries} (each includes the enumerator's own descriptor)");

        Bench("HandleCount (Refresh+HandleCount)", () => { p.Refresh(); _ = p.HandleCount; });
        Bench("Refresh+WorkingSet64", () => { p.Refresh(); _ = p.WorkingSet64; });
        Bench("Refresh+Threads.Count", () => { p.Refresh(); _ = p.Threads.Count; });
        Bench("OTel-style collection", () =>
        {
            p.Refresh();
            _ = p.WorkingSet64;
            _ = p.VirtualMemorySize64;
            _ = p.Threads.Count;
            _ = p.HandleCount;
        });
        Bench("OTel-style without Threads", () =>
        {
            p.Refresh();
            _ = p.WorkingSet64;
            _ = p.VirtualMemorySize64;
            _ = p.HandleCount;
        });

        int processCount = 0;
        Bench("Process.GetProcesses()", () =>
        {
            Process[] all = Process.GetProcesses();
            processCount = all.Length;
            foreach (Process x in all)
            {
                x.Dispose();
            }
        }, samples: 5, sampleMs: 300);

        if (output is not null)
        {
            var sb = new StringBuilder();
            sb.Append($"{{\"variant\":\"{variant}\",\"threads\":{actualThreads},\"fds\":{actualFds},\"processes\":{processCount},\"handleCount\":{handleCount},\"results\":[");
            sb.Append(string.Join(",", results.Select(r => $"{{\"name\":\"{r.Name}\",\"ns\":{r.Ns:F1},\"bytes\":{r.Bytes:F1},\"minNs\":{r.MinNs:F1},\"maxNs\":{r.MaxNs:F1}}}")));
            sb.Append("]}");
            File.WriteAllText(output, sb.ToString());
        }

        s_stop.Set();
        return 0;
    }

    private static (double Ns, double Bytes, double MinNs, double MaxNs) Measure(Action action, int samples, int sampleMs)
    {
        // Warm up so the code is tiered up.
        var sw = Stopwatch.StartNew();
        int warm = 0;
        while (sw.ElapsedMilliseconds < 1000 || warm < 50)
        {
            action();
            warm++;
        }

        // Calibrate the number of calls per sample.
        sw.Restart();
        int cal = 0;
        while (sw.ElapsedMilliseconds < 100 || cal < 3)
        {
            action();
            cal++;
        }

        int perSample = Math.Max(3, (int)(cal * (sampleMs / (double)sw.ElapsedMilliseconds)));

        var ns = new List<double>();
        var bytes = new List<double>();
        for (int s = 0; s < samples; s++)
        {
            GC.Collect();
            long a0 = GC.GetAllocatedBytesForCurrentThread();
            long t0 = Stopwatch.GetTimestamp();
            for (int i = 0; i < perSample; i++)
            {
                action();
            }

            long t1 = Stopwatch.GetTimestamp();
            long a1 = GC.GetAllocatedBytesForCurrentThread();
            ns.Add((t1 - t0) * 1e9 / Stopwatch.Frequency / perSample);
            bytes.Add((a1 - a0) / (double)perSample);
        }

        ns.Sort();
        bytes.Sort();
        return (ns[ns.Count / 2], bytes[bytes.Count / 2], ns[0], ns[^1]);
    }

    private static void EnsureThreads(int target)
    {
        while (ReadStatusInt("Threads:") < target)
        {
            var t = new Thread(() => s_stop.Wait()) { IsBackground = true };
            t.Start();
            s_keepAlive.Add(t);
            Thread.Sleep(2);
        }
    }

    private static void EnsureFds(int target)
    {
        // Open a mix of regular files, sockets and pipes (about 40%, 40% and 20% of the descriptors respectively).
        int i = 0;
        while (Directory.GetFileSystemEntries("/proc/self/fd").Length < target)
        {
            for (int j = 0; j < 20; j++)
            {
                switch (i++ % 5)
                {
                    case 0:
                    case 1:
                        s_keepAlive.Add(File.OpenHandle("/etc/hostname"));
                        break;
                    case 2:
                    case 3:
                        s_keepAlive.Add(new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp));
                        break;
                    default:
                        s_keepAlive.Add(new AnonymousPipeServerStream(PipeDirection.Out, HandleInheritability.None));
                        break;
                }
            }
        }
    }

    private static int ReadStatusInt(string key)
    {
        foreach (string line in File.ReadLines("/proc/self/status"))
        {
            if (line.StartsWith(key, StringComparison.Ordinal))
            {
                return int.Parse(line.AsSpan(key.Length).Trim());
            }
        }

        return -1;
    }
}
```

